//! Enzyme variant: plain Rust pricer, reverse mode generated by std::autodiff (LLVM-level).
#![feature(autodiff)]
#![feature(portable_simd)]
use std::autodiff::autodiff_reverse;
use std::simd::prelude::*;
use std::simd::StdFloat;
#[path = "../simd_portable.rs"] mod simd;
#[path = "../common.rs"] mod common;
use common::*;
use simd::{exp_f32, W};

/// Price of the GBM call (log-space exact scheme), lanes as arrays like the other variants.
#[autodiff_reverse(d_price, Duplicated, Const, Active)]
fn price(p: &[f32; 5], z: &[f32]) -> f32 {
    let (s0, r, sigma, t, k) = (p[0], p[1], p[2], p[3], p[4]);
    let dt = t / NS as f32;
    let drift = (r - 0.5 * sigma * sigma) * dt;
    let vsdt = sigma * dt.sqrt();
    let disc = exp_f32(-r * t);
    let x0 = s0.ln();
    let n_paths = NPATHS / W;
    let mut acc = [0f32; W];
    for i in 0..n_paths {
        let mut x = [x0; W];
        for kk in 0..NS {
            let base = (i * NS + kk) * W;
            for l in 0..W { x[l] = x[l] + drift + vsdt * z[base + l]; }
        }
        for l in 0..W {
            let v = exp_f32(x[l]) - k;
            acc[l] += if v > 0.0 { v } else { 0.0 };
        }
    }
    let mut s = 0f32;
    for l in 0..W { s += acc[l]; }
    s * disc / (n_paths * W) as f32
}

/// Same pricer with std::simd lanes and explicit FMA (still plain user code + one attribute).
#[autodiff_reverse(d_price_simd, Duplicated, Const, Active)]
fn price_simd(p: &[f32; 5], z: &[f32]) -> f32 {
    type S = Simd<f32, W>;
    let (s0, r, sigma, t, k) = (p[0], p[1], p[2], p[3], p[4]);
    let dt = t / NS as f32;
    let drift = S::splat((r - 0.5 * sigma * sigma) * dt);
    let vsdt = S::splat(sigma * dt.sqrt());
    let kk = S::splat(k);
    let x0 = S::splat(s0.ln());
    let n_paths = NPATHS / W;
    let mut acc = S::splat(0.0);
    for i in 0..n_paths {
        let mut x = x0;
        for st in 0..NS {
            let zv = unsafe { std::ptr::read_unaligned(z.as_ptr().add((i * NS + st) * W) as *const S) };
            x = vsdt.mul_add(zv, x + drift);
        }
        acc += (simd::V(x).exp().0 - kk).simd_max(S::splat(0.0));
    }
    acc.reduce_sum() * exp_f32(-r * t) / (n_paths * W) as f32
}

fn run_simd(p: [f32; 5], z: &[f32]) -> (f64, [f64; 5]) {
    let mut dp = [0f32; 5];
    let v = d_price_simd(&p, &mut dp, z, 1.0);
    (v as f64, dp.map(|x| x as f64))
}

fn run(p: [f32; 5], z: &[f32]) -> (f64, [f64; 5]) {
    let mut dp = [0f32; 5];
    let v = d_price(&p, &mut dp, z, 1.0);
    (v as f64, dp.map(|x| x as f64))
}

fn main() {
    let z = load_normals();
    let params = [100.0f32, 0.01, 0.2, 1.0, 100.0];
    let (price, g) = run(params, &z);
    report("rust enzyme f32", price, g);
    let (price, g) = run_simd(params, &z);
    report("rust enzyme std::simd f32", price, g);
    if std::env::args().any(|a| a == "--bench") {
        let (ms, chk) = best_ms(31, || { let (p, g) = run(params, &z); p + g.iter().sum::<f64>() });
        println!("rust  enzyme, plain lane loops          best ms {ms:.3}  chk {chk:.6}");
        let (ms, chk) = best_ms(31, || { let (p, g) = run_simd(params, &z); p + g.iter().sum::<f64>() });
        println!("rust  enzyme, std::simd + FMA           best ms {ms:.3}  chk {chk:.6}");
    }
}
